import{_ as t,o as a,c as n,a2 as o}from"./chunks/framework.1C62pOns.js";const p=JSON.parse('{"title":"Pro Agent Hub documentation","description":"","frontmatter":{},"headers":[],"relativePath":"en/index.md","filePath":"en/index.md","lastUpdated":1787839708000}'),r={name:"en/index.md"};function s(i,e,h,c,d,l){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="pro-agent-hub-documentation" tabindex="-1">Pro Agent Hub documentation <a class="header-anchor" href="#pro-agent-hub-documentation" aria-label="Permalink to &quot;Pro Agent Hub documentation&quot;">​</a></h1><p>Pro Agent Hub is a platform for building and running AI assistants: agents, teams, knowledge bases, MCP services, workflows and web applications — all configured through the UI, with Python where the UI does not reach.</p><h2 id="where-to-start" tabindex="-1">Where to start <a class="header-anchor" href="#where-to-start" aria-label="Permalink to &quot;Where to start&quot;">​</a></h2><p><strong><a href="/pro-agent-hub-installer/en/instalacao">Install</a></strong> — getting the platform running on Linux, Windows or macOS.</p><p><strong><a href="/pro-agent-hub-installer/en/funcoes/">Function reference</a></strong> — what you can call in each code screen. The platform has <strong>seven places</strong> where you write Python, and what is available differs in each: someone who learns <code>db_query(...)</code> in a Workflow and writes the same in an Agent tool gets a <code>NameError</code>. This section says exactly what exists where.</p><h2 id="about-this-documentation" tabindex="-1">About this documentation <a class="header-anchor" href="#about-this-documentation" aria-label="Permalink to &quot;About this documentation&quot;">​</a></h2><p>The function reference is <strong>generated from the source code</strong> — from the same scope builders the platform uses to run your code. A new operation shows up here without anyone having to remember it; a removed one disappears. There is no hand-written list to go stale.</p><p>The screen-by-screen manual (with images) is in preparation.</p>',8)])])}const m=t(r,[["render",s]]);export{p as __pageData,m as default};
